// Obtener datos de pedidos
const pedidos = $('Get Pedidos').all();

// ===== MÉTRICAS GENERALES =====
const totalPedidos = pedidos.length;
const pedidosEntregados = pedidos.filter(p => p.json.estado === 'Entregado').length;
const pedidosEnProceso = pedidos.filter(p => ['Confirmado', 'En camino'].includes(p.json.estado)).length;
const pedidosCancelados = pedidos.filter(p => p.json.estado === 'Cancelado').length;

// Calcular valores monetarios
const valorTotalPedidos = pedidos.reduce((sum, p) => sum + (parseFloat(p.json.valor_final) || 0), 0);
const valorPromedioPedido = totalPedidos > 0 ? valorTotalPedidos / totalPedidos : 0;

// Tasa de conversión
const tasaConversion = totalPedidos > 0 ? ((pedidosEntregados / totalPedidos) * 100).toFixed(1) : 0;

// ===== PEDIDOS POR ESTADO =====
const pedidosPorEstado = pedidos.reduce((acc, p) => {
  const estado = p.json.estado;
  acc[estado] = (acc[estado] || 0) + 1;
  return acc;
}, {});

// ===== PEDIDOS POR ZONA =====
const pedidosPorZona = pedidos.reduce((acc, p) => {
  const zona = p.json.zona_domicilio;
  acc[zona] = (acc[zona] || 0) + 1;
  return acc;
}, {});

// ===== PEDIDOS POR CIUDAD =====
const pedidosPorCiudad = pedidos.reduce((acc, p) => {
  const ciudad = p.json.ciudad || 'Sin especificar';
  acc[ciudad] = (acc[ciudad] || 0) + 1;
  return acc;
}, {});

// ===== EVOLUCIÓN EN EL TIEMPO (últimos 30 días) =====
const hoy = new Date();
const diasData = [];
for (let i = 29; i >= 0; i--) {
  const fecha = new Date(hoy);
  fecha.setDate(fecha.getDate() - i);
  const fechaStr = fecha.toISOString().split('T')[0];

  const pedidosDia = pedidos.filter(p => {
    const pedidoFecha = new Date(p.json.fecha_pedido).toISOString().split('T')[0];
    return pedidoFecha === fechaStr;
  }).length;

  diasData.push({
    fecha: fechaStr,
    dia: fecha.getDate(),
    mes: fecha.getMonth() + 1,
    pedidos: pedidosDia
  });
}

// ===== MÉTRICAS POR PERÍODO =====
const fechaUnMesAtras = new Date();
fechaUnMesAtras.setMonth(fechaUnMesAtras.getMonth() - 1);
const pedidosUltimoMes = pedidos.filter(p => new Date(p.json.fecha_pedido) >= fechaUnMesAtras).length;

const fechaUnaSemanaAtras = new Date();
fechaUnaSemanaAtras.setDate(fechaUnaSemanaAtras.getDate() - 7);
const pedidosUltimaSemana = pedidos.filter(p => new Date(p.json.fecha_pedido) >= fechaUnaSemanaAtras).length;

// ===== VALOR POR ZONA =====
const valorPorZona = pedidos.reduce((acc, p) => {
  const zona = p.json.zona_domicilio;
  if (!acc[zona]) {
    acc[zona] = { total: 0, cantidad: 0 };
  }
  acc[zona].total += parseFloat(p.json.valor_final) || 0;
  acc[zona].cantidad += 1;
  return acc;
}, {});

// ===== FECHA DE ACTUALIZACIÓN =====
const fechaActualizacion = new Date().toLocaleString('es-CO', {
  timeZone: 'America/Bogota',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
});

// ===== OBTENER LISTAS ÚNICAS PARA FILTROS =====
const zonasUnicas = [...new Set(pedidos.map(p => p.json.zona_domicilio))].sort();
const ciudadesUnicas = [...new Set(pedidos.map(p => p.json.ciudad || 'Sin especificar'))].sort();
const estadosUnicos = [...new Set(pedidos.map(p => p.json.estado))].sort();

// ===== DATOS COMPLETOS DE PEDIDOS PARA TABLA =====
const pedidosDetalle = pedidos.map(p => ({
  id: p.json.pedido_id,
  fecha: new Date(p.json.fecha_pedido).toLocaleString('es-CO', { 
    year: 'numeric', 
    month: '2-digit', 
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit'
  }),
  estado: p.json.estado,
  zona: p.json.zona_domicilio,
  ciudad: p.json.ciudad || 'N/A',
  valor: parseFloat(p.json.valor_final) || 0,
  usuario: p.json.nombre_usuario,
  domiciliario: p.json.domiciliario_asignado || 'Sin asignar'
})).sort((a, b) => b.id - a.id); // Más recientes primero

// Return all metrics
return [{
  json: {
    metricas: {
      total: totalPedidos,
      entregados: pedidosEntregados,
      enProceso: pedidosEnProceso,
      cancelados: pedidosCancelados,
      valorTotal: Math.round(valorTotalPedidos),
      valorPromedio: Math.round(valorPromedioPedido),
      tasaConversion: parseFloat(tasaConversion),
      ultimoMes: pedidosUltimoMes,
      ultimaSemana: pedidosUltimaSemana
    },
    porEstado: pedidosPorEstado,
    porZona: pedidosPorZona,
    porCiudad: pedidosPorCiudad,
    valorPorZona: valorPorZona,
    evolucion: diasData,
    filtros: {
      zonas: zonasUnicas,
      ciudades: ciudadesUnicas,
      estados: estadosUnicos
    },
    pedidosDetalle: pedidosDetalle,
    meta: {
      fechaActualizacion: fechaActualizacion
    }
  }
}];
